<?php get_header(); $term=get_queried_object(); ?><main class="section service-archive"><div class="eyebrow">НАПРАВЛЕНИЕ ПРОДВИЖЕНИЯ</div><h1><?php echo esc_html($term->name);?></h1><p class="lead"><?php echo esc_html($term->description?:'Конкретные услуги этого направления для продвижения песни и артиста.');?></p><nav class="service-direction-nav" aria-label="Другие направления"><a href="<?php echo esc_url(get_post_type_archive_link('orh_service'));?>">Все направления</a><?php $groups=orh_service_groups();foreach($groups as $group){if((int)$group->term_id===(int)$term->term_id)continue;$url=get_term_link($group);if(!is_wp_error($url))echo '<a href="'.esc_url($url).'">'.esc_html($group->name).'</a>';}?></nav><div class="service-grid"><?php if(have_posts()):while(have_posts()):the_post();$thumb=orh_media_url(get_the_ID(),'large');$lb=get_post_meta(get_the_ID(),'orh_service_label',true);$ac=get_post_meta(get_the_ID(),'orh_service_accent',true)?:'acid';?><a class="service-card <?php echo esc_attr($ac);?>" href="<?php the_permalink();?>"><div class="service-visual" <?php if($thumb)echo 'style="background-image:url(\''.esc_url($thumb).'\')"';?>><span><?php echo esc_html($lb?:'УСЛУГА');?></span><i>↗</i></div><div class="service-card-copy"><h3><?php the_title();?></h3><p><?php echo esc_html(get_the_excerpt());?></p><strong>Подробнее →</strong></div></a><?php endwhile;else:?><div class="empty">В этом направлении пока нет услуг.</div><?php endif;?></div></main><?php get_footer();?>